window.kbPageData["views/entry/k-14732ea9142d41d2"] = {"key":"entry/k-14732ea9142d41d2","state":{"route":"entry/k-14732ea9142d41d2"},"node":{"id":"k-14732ea9142d41d2","mode":"k","title":"同步","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“同步”的时间一致义","“同步”的含义"],"qs":["国考 2025 地市级 行测#41","国考 2025 行政执法 行测#44"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"指两个或多个相互关联的过程在时间上同时发生，或按一致的步调推进。","review":{"definition":"指两个或多个相互关联的过程在时间上同时发生，或按一致的步调推进。","explanation":"第44题说风电、光伏发电有间歇性，用电需求又时多时少。“不一定同步”表示有电可供的时段与需要用电的时段未必重合，储能可以把一部分电留到需要时使用。“匹配”也能描述供需是否相适应，“同步”更明确地指出这里的时间关系。","references":[],"evidence":"应体现能量的产生和使用在时间上存在不一致性。","disposition":"独立词条","basis":"据原题和解析编释。","title":"同步","related":[],"examFocus":{"国考 2025 地市级 行测#41":"结合发电的间歇性判断第一空要描述的产用关系，再用“时多时少”检验第二空能否概括用电需求的变化。"}},"readings":[{"origin":"k-14732ea9142d41d2","title":"同步","qs":["国考 2025 行政执法 行测#44"],"definition":"指两个或多个相互关联的过程在时间上同时发生，或按一致的步调推进。","explanation":"第44题说风电、光伏发电有间歇性，用电需求又时多时少。“不一定同步”表示有电可供的时段与需要用电的时段未必重合，储能可以把一部分电留到需要时使用。“匹配”也能描述供需是否相适应，“同步”更明确地指出这里的时间关系。","evidence":"应体现能量的产生和使用在时间上存在不一致性。","doubt":"","references":[]},{"origin":"k-75abee92005a4e3d","title":"同步","qs":["国考 2025 地市级 行测#41"],"definition":"指相互关联的事物在时间上同时发生，或在进行的节奏、进度上保持一致。","explanation":"第41题中，风电和光伏发电具有间歇性，用电需求也时多时少，所以发电较多的时段可能与用电需求较高的时段错开。“同步”直接点明这种时序关系，“匹配”则泛指在某一方面相适应。","evidence":"存在不同时间尺度的间歇性","doubt":"","references":[]}]},"questions":{"国考 2025 地市级 行测#41":{"paper":"国考 2025 地市级 行测","n":41,"mod":"言语理解与表达","src":["31f401e91aef8d11365d.pdf",6],"asrc":["8cece062c7c079b53130.pdf",14],"card":"fd9afd1385fdebe87ae360a1","links":[{"id":"k-14732ea9142d41d2","role":"直接考查","why":"需识别“同步”所指的时间进程一致，才能将其与发电和用电的时序联系起来。"}]},"国考 2025 行政执法 行测#44":{"paper":"国考 2025 行政执法 行测","n":44,"mod":"言语理解与表达","src":["d8efe4e19862104d89c8.pdf",7],"asrc":["e2c4b1970d2b49eac0fd.pdf",15],"card":"4d25c44ed64d0e7565efc283","links":[{"id":"k-14732ea9142d41d2","role":"直接考查","why":"首空需辨别哪个词能具体表达产生与使用在时间上的一致关系。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-14732ea9142d41d2":[["国考 2025 地市级 行测#41","国考 2025 行政执法 行测#44"]]}};
